from pathlib import Path
import shutil
out=Path('/app/output')
patterns=['canvas_*.png','ink_v*.npy','labels.png','pathoverlay.png','practice_test.png','practice_test2.png','side.png','skeleton.png','trajectory_v*.npz','rcb_session_log.jsonl']
